import{_ as e,o as a,c as i,i as o}from"./chunks/framework.DP1yFSuu.js";const g=JSON.parse('{"title":"Guidance","description":"","frontmatter":{},"headers":[],"relativePath":"guidance/index.md","filePath":"guidance/index.md"}'),r={name:"guidance/index.md"};function n(s,t,l,d,h,p){return a(),i("div",null,[...t[0]||(t[0]=[o('<h1 id="guidance" tabindex="-1">Guidance <a class="header-anchor" href="#guidance" aria-label="Permalink to &quot;Guidance&quot;">​</a></h1><p>Cobalt Design System provides more than components. It offers guidance for adopting tokens, mapping existing UI, migrating application slices, and building cohesive product experiences as the system matures.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>These resources are primarily for application teams working with Cobalt in real products. Cobalt is currently in alpha, so existing applications should adopt it incrementally instead of planning a broad rewrite.</p><h2 id="sections" tabindex="-1">Sections <a class="header-anchor" href="#sections" aria-label="Permalink to &quot;Sections&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>Description</th></tr></thead><tbody><tr><td><a href="./adoption.html">Adoption Plan</a></td><td>Staged adoption model for existing applications, including alpha guardrails.</td></tr><tr><td><a href="./element-mapping.html">Element Mapping</a></td><td>How to progressively opt native HTML into Cobalt baseline styles.</td></tr><tr><td><a href="./migration.html">Migration Guide</a></td><td>A scoped migration flow for one application route, workflow, or product slice.</td></tr><tr><td><a href="./principles.html">Design Principles</a></td><td>The core values that drive every decision in Cobalt.</td></tr><tr><td><a href="./content.html">Content &amp; Writing</a></td><td>Voice, tone, capitalization, error messages, and formatting rules.</td></tr><tr><td><a href="./../getting-started/developers.html">Getting Started for Developers</a></td><td>Environment setup, project structure, and first steps with Cobalt.</td></tr></tbody></table><h2 id="who-is-this-for" tabindex="-1">Who is this for? <a class="header-anchor" href="#who-is-this-for" aria-label="Permalink to &quot;Who is this for?&quot;">​</a></h2><ul><li><strong>Application teams</strong> - Plan realistic adoption for existing products.</li><li><strong>Developers</strong> - Install Cobalt, adopt tokens, and migrate scoped slices safely.</li><li><strong>Designers</strong> - Align current UI with Cobalt patterns and identify design-system gaps.</li><li><strong>Tech leads</strong> - Decide what can move now, what should stay local, and what needs roadmap support.</li><li><strong>Content authors</strong> - Write clear, consistent copy that aligns with the Cobalt voice.</li></ul><h2 id="how-to-use-these-guides" tabindex="-1">How to use these guides <a class="header-anchor" href="#how-to-use-these-guides" aria-label="Permalink to &quot;How to use these guides&quot;">​</a></h2><p>For existing applications, start with the <a href="./adoption.html">Adoption Plan</a>, then use <a href="./element-mapping.html">Element Mapping</a> to scope baseline styles before following the <a href="./migration.html">Migration Guide</a>. For new projects, start with <a href="./../getting-started/developers.html">Getting Started for Developers</a> and the <a href="./principles.html">Design Principles</a>.</p><blockquote><p><strong>Tip:</strong> Treat migration as a product-slice decision, not a full-application rewrite.</p></blockquote><h2 id="contributing" tabindex="-1">Contributing <a class="header-anchor" href="#contributing" aria-label="Permalink to &quot;Contributing&quot;">​</a></h2><p>If you spot an error or want to propose a new guideline, open an issue in the Cobalt repository with the <code>guidance</code> label. All changes to this section go through the same review process as component code.</p><hr><p><em>Last updated: May 2026</em></p>',15)])])}const u=e(r,[["render",n]]);export{g as __pageData,u as default};
